        self.next = next
        self.data = data


def find_loop_start(head):
    if head is None or head.next is None:
        return None
    slow = head
    fast = head
    while fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if fast is None:
            return None
        if slow == fast:
            break
    slow = head
    while slow != fast:
        slow = slow.next
        fast = fast.next
        if fast is None:
            return None
    return slow


